mapper.insert:
INSERT INTO featured_resource(id, resource_id, featured_title, featured_desc, cover_url, sort, status, created_by, created_at, updated_at)
VALUES (null, #{featuredResourceAddDTO.resourceId}, #{featuredResourceAddDTO.featuredTitle}, #{featuredResourceAddDTO.featuredDesc}, #{featuredResourceAddDTO.coverUrl}
       , #{featuredResourceAddDTO.sort}, #{featuredResourceAddDTO.status}, #{userId}, NOW(), NOW())

mapper.update:
update featured_resource
featured_title = #{featuredResourceUpdateDTO.featuredTitle}, featured_desc = #{featuredResourceUpdateDTO.featuredDesc}, cover_url = #{featuredResourceUpdateDTO.coverUrl}, sort = #{featuredResourceUpdateDTO.sort}, status = #{featuredResourceUpdateDTO.status},
where id = #{id}

mapper.select:
select
f.id,f.resource_id,r.title,r.description,f.cover_url,r.file_url,r.file_size,r.file_type,r.download_count,r.create_time,f.sort,f.status
from featured_resource as f left join resource as r on f.resource_id = r.id where f.id = #{resId}
